-- ORGANIZED FULL TEST SEED
-- Run after importing enrollment_system_lms_final_schema_clean.sql.
-- This script clears existing data, resets IDs, and rebuilds a consistent test dataset.
-- Includes: active SY 2026-2027, curriculum-linked sections, professor schedules, LMS classes, quizzes, and questions.
-- Excludes: LMS materials, quiz attempts, and quiz answers.
-- Test password for all seeded admin/professor/student accounts: password123
SET FOREIGN_KEY_CHECKS=0;
DELETE FROM `quiz_attempt_answers`;
DELETE FROM `quiz_attempts`;
DELETE FROM `quiz_questions`;
DELETE FROM `quizzes`;
DELETE FROM `lms_materials`;
DELETE FROM `lms_notifications`;
DELETE FROM `lms_classes`;
DELETE FROM `grades`;
DELETE FROM `enrollment_payments`;
DELETE FROM `enrollment_documents`;
DELETE FROM `entrance_exam_results`;
DELETE FROM `enrollments`;
DELETE FROM `class_schedules`;
DELETE FROM `sections`;
DELETE FROM `student_family_members`;
DELETE FROM `educational_background`;
DELETE FROM `students`;
DELETE FROM `professor_password_resets`;
DELETE FROM `professors`;
DELETE FROM `admin_password_resets`;
DELETE FROM `admins`;
DELETE FROM `grading_periods`;
DELETE FROM `curriculum`;
DELETE FROM `school_years`;
DELETE FROM `rooms`;
DELETE FROM `subjects`;
DELETE FROM `strands`;
DELETE FROM `curriculum_versions`;
ALTER TABLE `quiz_attempt_answers` AUTO_INCREMENT=1;
